main.c:

	#include <stdint.h>
	#include <zephyr/drivers/fpga.h>
	#include <zephyr/kernel.h>

	const struct device *ice40 = DEVICE_DT_GET(DT_NODELABEL(ice40));

	uint8_t buffer[104090] __attribute__((aligned(4)));

	int main(void)
	{
		return fpga_load(
			ice40,
			(uint32_t *)buffer,
			ARRAY_SIZE(buffer));
	}

prj.conf:

	CONFIG_COMPILER_OPT="-Wall -Werror"
	CONFIG_DEBUG_OPTIMIZATIONS=y
	CONFIG_LOG=y
	CONFIG_LOG_BUFFER_SIZE=4096
	CONFIG_GPIO=y
	CONFIG_SPI=y
	CONFIG_FPGA=y
	CONFIG_ICE40_FPGA=y

nucleo_f767zi.overlay:

	&spi1 {
		status = "okay";
		pinctrl-0 = <&spi1_sck_pa5>,
			<&spi1_miso_pa6>,
			<&spi1_mosi_pa7>;
		pinctrl-names = "default";
		cs-gpios = <&gpiod 14 GPIO_ACTIVE_LOW>;

		ice40: ice40@0 {
			compatible = "lattice,ice40-fpga";
			status = "okay";
			spi-max-frequency = <1000000>;
			reg = <0x0>;
			creset-gpios = <&gpiob 8 GPIO_ACTIVE_LOW>; // CRESET_B
			cdone-gpios = <&gpiob 9 GPIO_ACTIVE_HIGH>;  // CDONE
			load-mode = <1>;
		};
	};

